def svg(name,title,lines):
    y=220;parts=['<svg xmlns="http://www.w3.org/2000/svg" width="1920" height="1080" viewBox="0 0 1920 1080"><rect width="1920" height="1080" fill="#101b2a"/><g fill="#eef4fb" font-family="Microsoft YaHei, sans-serif">',f'<text x="120" y="130" font-size="54" font-weight="700">{html.escape(title)}</text>']
    for label,desc in lines:
        parts += [f'<text x="120" y="{y}" font-size="36" fill="#6cdbca">{html.escape(label)}</text>',f'<text x="150" y="{y+62}" font-size="29">{html.escape(desc)}</text>'];y+=190
    parts += ['<text x="120" y="1020" font-size="25" fill="#bbc8d6">TileLab 单片瓷砖停驻检测原型　指标范围以实测记录为准</text></g></svg>'];(O/name).write_text(''.join(parts),encoding='utf8')
